L000086	\newlabel{tab:ES}{{S1}{8}{Formation energies of Schottky pairs in eV for the NaCl films. For the supported NaCl layers, the values are for NaCl in hollow (top) registry with respect to Ag(100). As reference, the last two columns show the total energy differences between the corresponding top and hollow registries of the pristine films}{table.1}{}}
L000087	\@writefile{lof}{\contentsline {figure}{\numberline {S8}{\ignorespaces Sketch of the atoms and bonds of RE adsorption with the definitions of the structural quantities shown in Tab.\nobreakspace  {}\ref  {tab:DeltaE_geom_6l}, \ref  {tab:DeltaE_geom_ag3l}, and \ref  {tab:DeltaE_geom_ag2l}. The bonds are artificially distorted and bucklings exaggerated to guide the eye. Color code: Cl in green, Na in blue and RE in gray. Definition of the distances $d_1 = d (\mathrm  {RE-Cl}) $, $d_2 = d (\mathrm  {RE-Na}) $ and $b$ (buckling of the topmost NaCl plane) for a RE atom (a) physisorbed at a top-Cl site, (b) at the bridge site of the NaCl lattice, and (c) substituting a surface Na atom. We note that in the top-Cl and top-Na cases buckling is typically weak, whereas in the bridge case it is stronger, due to the RE-Cl bonding. In the substitutional case (c) the $b$ value includes the RE atom height and we use $d_0$ for the RE atom with respect to the average height of the NaCl plane, with $d_0<0$ to indicate that the RE atom lies below such plane. }}{8}{figure.8}\protected@file@percent }
L000088	\newlabel{fig:relax_detail}{{S8}{8}{Sketch of the atoms and bonds of RE adsorption with the definitions of the structural quantities shown in Tab.~\ref {tab:DeltaE_geom_6l}, \ref {tab:DeltaE_geom_ag3l}, and \ref {tab:DeltaE_geom_ag2l}. The bonds are artificially distorted and bucklings exaggerated to guide the eye. Color code: Cl in green, Na in blue and RE in gray. Definition of the distances $d_1 = d (\mathrm {RE-Cl}) $, $d_2 = d (\mathrm {RE-Na}) $ and $b$ (buckling of the topmost NaCl plane) for a RE atom (a) physisorbed at a top-Cl site, (b) at the bridge site of the NaCl lattice, and (c) substituting a surface Na atom. We note that in the top-Cl and top-Na cases buckling is typically weak, whereas in the bridge case it is stronger, due to the RE-Cl bonding. In the substitutional case (c) the $b$ value includes the RE atom height and we use $d_0$ for the RE atom with respect to the average height of the NaCl plane, with $d_0<0$ to indicate that the RE atom lies below such plane}{figure.8}{}}
