L000094	\@writefile{lot}{\contentsline {table}{\numberline {S2}{\ignorespaces  Gd and Eu adsorption energies $\Delta E_{ads}^{(6L)}$ in eV at the top-Na, bridge and Na substitutional sites on NaCl 6\,ML, given with respect to the physisorption energy at the top-Cl as reference configuration, for both vdW functionals. For the substitutional case, the value $\Delta \tilde  E_{ads\star }^{(6L)}$ contains the energy needed to create a Schottky defect, which are taken from Tab.\nobreakspace  {}\ref  {tab:ES}. The distances in the relaxed structures are in {\r A} (see Fig.\nobreakspace  {}\ref  {fig:relax_detail} for definitions). As reference value, we note that the buckling at clean NaCl(100) is in the 0.09-0.11\,{\r A} range for the studied functionals, with protruding Cl atoms. In the bridge site, the RE atom pulls the neighboring Cl atoms outward. The energetically preferred site is marked in grey. }}{10}{table.2}\protected@file@percent }
L000095	\newlabel{tab:DeltaE_geom_6l}{{S2}{10}{Gd and Eu adsorption energies $\Delta E_{ads}^{(6L)}$ in eV at the top-Na, bridge and Na substitutional sites on NaCl 6\,ML, given with respect to the physisorption energy at the top-Cl as reference configuration, for both vdW functionals. For the substitutional case, the value $\Delta \tilde E_{ads\star }^{(6L)}$ contains the energy needed to create a Schottky defect, which are taken from Tab.~\ref {tab:ES}. The distances in the relaxed structures are in {\AA } (see Fig.~\ref {fig:relax_detail} for definitions). As reference value, we note that the buckling at clean NaCl(100) is in the 0.09-0.11\,{\AA } range for the studied functionals, with protruding Cl atoms. In the bridge site, the RE atom pulls the neighboring Cl atoms outward. The energetically preferred site is marked in grey}{table.2}{}}
